import os
import sqlite3
from datetime import datetime
from functools import wraps

from flask import abort, g, redirect, render_template_string, request, session, url_for
from werkzeug.security import check_password_hash, generate_password_hash

from nexus_api import PUBLIC_ENDPOINT_PREFIXES, PUBLIC_OAUTH_ENDPOINTS

AUTH_ROLES = ("admin", "manager", "sales_rep")


def ensure_auth_schema(db_connect):
    """Create the shared application user table and optionally bootstrap the first admin."""
    with db_connect() as connection:
        connection.execute(
            """
            CREATE TABLE IF NOT EXISTS app_users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                email TEXT NOT NULL UNIQUE,
                display_name TEXT NOT NULL,
                password_hash TEXT NOT NULL,
                role TEXT NOT NULL DEFAULT 'sales_rep',
                active INTEGER NOT NULL DEFAULT 1,
                created_at TEXT NOT NULL,
                last_login_at TEXT NOT NULL DEFAULT '',
                os_access INTEGER NOT NULL DEFAULT 0
            )
            """
        )
        columns = {row[1] for row in connection.execute("PRAGMA table_info(app_users)").fetchall()}
        if "os_access" not in columns:
            connection.execute("ALTER TABLE app_users ADD COLUMN os_access INTEGER NOT NULL DEFAULT 0")
            # Preserve the current administrator workflow when this feature gate first lands.
            # Reps/managers remain Sales-only by default; admins can selectively enable OS access for anyone.
            connection.execute("UPDATE app_users SET os_access=1 WHERE role='admin'")
        connection.commit()

        bootstrap_email = os.environ.get("INITIAL_ADMIN_EMAIL", "").strip().lower()
        bootstrap_password = os.environ.get("INITIAL_ADMIN_PASSWORD", "")
        bootstrap_name = os.environ.get("INITIAL_ADMIN_NAME", "Administrator").strip() or "Administrator"
        count = connection.execute("SELECT COUNT(*) FROM app_users").fetchone()[0]
        if count == 0 and bootstrap_email and bootstrap_password:
            connection.execute(
                "INSERT INTO app_users (email,display_name,password_hash,role,active,created_at,last_login_at,os_access) VALUES (?,?,?,?,?,?,?,?)",
                (
                    bootstrap_email, bootstrap_name, generate_password_hash(bootstrap_password),
                    "admin", 1, datetime.now().isoformat(timespec="seconds"), "", 1,
                ),
            )
            connection.commit()


def admin_required(view_func):
    @wraps(view_func)
    def wrapped(*args, **kwargs):
        user = getattr(g, "current_user", None)
        if not user or user.get("role") != "admin":
            abort(403)
        return view_func(*args, **kwargs)
    return wrapped


def territory_manager_required(view_func):
    @wraps(view_func)
    def wrapped(*args, **kwargs):
        user = getattr(g, "current_user", None)
        if not user or user.get("role") not in {"admin", "manager"}:
            abort(403)
        return view_func(*args, **kwargs)
    return wrapped


