def register_auth_routes(app, *, db_connect, get_active_trip_id, trip_row_for_current_user, audit_event):
    def get_user_by_id(user_id):
        if not user_id:
            return None
        with db_connect() as connection:
            connection.row_factory = sqlite3.Row
            row = connection.execute(
                "SELECT id,email,display_name,role,active,created_at,last_login_at,os_access FROM app_users WHERE id=?",
                (user_id,),
            ).fetchone()
            return dict(row) if row else None

    def user_count():
        try:
            with db_connect() as connection:
                return int(connection.execute("SELECT COUNT(*) FROM app_users").fetchone()[0])
        except Exception:
            return 0

    @app.before_request
    def load_and_require_user():
        # PWA discovery files must be readable before login. If these routes are
        # redirected to the login page, browsers receive HTML instead of the
        # manifest/service worker and can only create a normal bookmark.
        public_endpoints = {
            "login",
            "cloud_health",
            "hubspot_sync.webhooks",
            "static",
            "pwa_manifest",
            "pwa_service_worker",
            "pwa_offline",
        }
        user_id = session.get("user_id")
        g.current_user = get_user_by_id(user_id) if user_id else None
        if g.current_user and not g.current_user.get("active"):
            session.clear()
            g.current_user = None
        # OAuth metadata/token endpoints and the bearer-token API authenticate themselves.
        public_endpoints |= PUBLIC_OAUTH_ENDPOINTS
        if (request.endpoint in public_endpoints or request.endpoint is None
                or str(request.endpoint).startswith(PUBLIC_ENDPOINT_PREFIXES)):
            return None
        if not g.current_user:
            next_path = request.full_path if request.query_string else request.path
            return redirect(url_for("login", next=next_path))

        # Riverlea OS feature gate. Sales Assistant functionality remains available to every
        # authorised user; unfinished OS modules require explicit per-user access.
        if not bool(int(g.current_user.get("os_access") or 0)):
            path = request.path.rstrip("/") or "/"
            os_only_prefixes = ("/meetings", "/issues", "/rocks", "/scorecard", "/nexus-meet", "/qc")
            if any(path == prefix or path.startswith(prefix + "/") for prefix in os_only_prefixes):
                abort(403)
        return None

    @app.context_processor
    def inject_auth_context():
        current_user = getattr(g, "current_user", None)
        nav_active_trip_id = None
        if current_user:
            try:
                candidate_id = get_active_trip_id()
                if candidate_id:
                    with db_connect() as connection:
                        nav_active_trip_id = candidate_id if trip_row_for_current_user(connection, candidate_id) else None
            except Exception:
                nav_active_trip_id = None
        return {"current_user": current_user, "nav_active_trip_id": nav_active_trip_id}

    @app.route("/login", methods=["GET", "POST"], endpoint="login")
    def login():
        if getattr(g, "current_user", None):
            return redirect(url_for("control_centre"))
        error = ""
        next_path = request.values.get("next", "") or url_for("control_centre")
        if not (next_path.startswith("/") and not next_path.startswith("//")):
            next_path = url_for("control_centre")
        if request.method == "POST":
            email = request.form.get("email", "").strip().lower()
            password = request.form.get("password", "")
            with db_connect() as connection:
                connection.row_factory = sqlite3.Row
                row = connection.execute(
                    "SELECT id,email,display_name,password_hash,role,active FROM app_users WHERE lower(email)=lower(?)",
                    (email,),
                ).fetchone()
                user = dict(row) if row else None
                if user and user.get("active") and check_password_hash(user.get("password_hash", ""), password):
                    session.clear()
                    session.permanent = True
                    session["user_id"] = user["id"]
                    connection.execute(
                        "UPDATE app_users SET last_login_at=? WHERE id=?",
                        (datetime.now().isoformat(timespec="seconds"), user["id"]),
                    )
                    connection.commit()
                    audit_event("login", f"User signed in: {user['email']}")
                    return redirect(next_path)
            error = "Email or password is incorrect."
        return render_template_string(LOGIN_PAGE, error=error, next_path=next_path, no_users=(user_count() == 0))

    @app.route("/logout", endpoint="logout")
    def logout():
        email = (getattr(g, "current_user", None) or {}).get("email", "")
        session.clear()
        if email:
            audit_event("logout", f"User signed out: {email}")
        return redirect(url_for("login"))

    return {"login": login, "logout": logout}
